export const mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:0;
export const finite=v=>(typeof v==='number'||typeof v==='string')&&String(v).trim()!==''&&Number.isFinite(Number(v));
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const features=['oil','water','pressure','injection','water_cut'];
export const fieldInfo={well_id:['井号','文本'],date:['日期','YYYY-MM-DD'],oil:['日产油体积','标准立方米/日'],water:['日产水体积','标准立方米/日'],liquid:['日产液体积','标准立方米/日'],gas:['日产气体积','标准立方米/日'],pressure:['井下压力','兆帕'],annulus:['环空压力','兆帕'],injection:['注水体积','标准立方米/日'],injection_pressure:['注水压力','兆帕'],water_cut:['含水率','百分比0–100'],liquid_level:['动液面深度','米，向下为正'],pump_efficiency:['泵效','百分比0–100'],pump_card_class:['示功图解释工况','如供液不足、泵漏失'],absorption_index:['吸水指数','标准立方米/(日·兆帕)'],response_strength:['注采响应强度','0–1研究特征'],expected_oil:['独立模型产油预测','标准立方米/日'],x:['空间坐标','归一化0–1'],t:['时间坐标','归一化0–1'],label:['正常/异常标签','0或1'],root_cause:['确诊原因','多标签以|分隔'],commission_date:['投产日期','YYYY-MM-DD'],measure_date:['最近措施日期','YYYY-MM-DD'],tracer_weight:['井间示踪剂响应权重','非负、无量纲']};
export function parseCSV(text){text=String(text).replace(/^\ufeff/,'');const rows=[];let row=[],s='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){s+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(s);s='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(s);if(row.some(x=>x.trim()))rows.push(row);row=[];s='';}else s+=c;}if(quote)throw Error('CSV引号未闭合');row.push(s);if(row.some(x=>x.trim()))rows.push(row);if(!rows.length)throw Error('文件为空');const keys=rows.shift().map(x=>x.trim());if(new Set(keys).size!==keys.length)throw Error('CSV存在重复列名');return rows.map(r=>Object.fromEntries(keys.map((k,i)=>[k,r[i]??''])));}
export function csv(rows){if(!rows.length)return '';const ks=[...new Set(rows.flatMap(Object.keys))];const safe=v=>{let s=String(v??'');if(/^[=+@\t\r]/.test(s)||(/^\-/.test(s)&&!finite(s)))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return '\ufeff'+[ks.map(safe).join(','),...rows.map(r=>ks.map(k=>safe(r[k])).join(','))].join('\r\n');}
export function normalizeRows(rows){return rows.map((a,i)=>{const r={...a};for(const k of Object.keys(fieldInfo))if(!['well_id','date','root_cause','commission_date','measure_date','pump_card_class'].includes(k)&&finite(r[k]))r[k]=Number(r[k]);if(finite(r.oil)&&finite(r.water)){r.liquid=Number(r.oil)+Number(r.water);if(!finite(r.water_cut)&&r.liquid>0)r.water_cut=100*Number(r.water)/r.liquid;}r.id=r.id??`${r.well_id??'W'}-${r.date??i}-${i}`;return r;});}
export function validateRows(rows,required=[]){if(!Array.isArray(rows)||!rows.length)throw Error('没有有效数据行');if(rows.length>100000)throw Error('浏览器单批最多100000行，请分批上传');for(const [i,r]of rows.entries()){for(const k of required){if(k==='root_cause'){if(!String(r[k]??'').trim())throw Error(`第${i+1}行缺少确诊原因root_cause`);}else if(!finite(r[k]))throw Error(`第${i+1}行 ${k} 缺失或不是有限数值`);}if(r.date&&!Number.isFinite(Date.parse(r.date)))throw Error(`第${i+1}行日期无效`);if(required.includes('water_cut')&&finite(r.water_cut)&&(r.water_cut<0||r.water_cut>100))throw Error(`第${i+1}行含水率应为0–100`);}return rows;}
export function selectUsableRows(rows,required){return rows.filter(r=>required.every(k=>k==='root_cause'?String(r[k]??'').trim():finite(r[k]))&&(!required.includes('water_cut')||(r.water_cut>=0&&r.water_cut<=100))&&['oil','water','liquid','injection'].every(k=>!required.includes(k)||Number(r[k])>=0));}
export function splitData(rows,ratios=[70,15,15],method='time',seed=42){if(ratios.length!==3||ratios.some(x=>!finite(x)||Number(x)<=0)||Math.abs(ratios.reduce((a,b)=>a+Number(b),0)-100)>1e-6)throw Error('训练、验证、测试比例均须大于0且合计100%');if(rows.length<10)throw Error('整体划分至少需要10行');let a=[...rows];if(method==='random'){let s=Number(seed)>>>0;const rand=()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};for(let i=a.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[a[i],a[j]]=[a[j],a[i]];}}else if(method==='well'){const wells=[...new Set(a.map(r=>r.well_id))].sort();if(wells.length<3)throw Error('按井划分至少需要3口井');const n=Math.max(1,Math.min(wells.length-2,Math.floor(wells.length*ratios[0]/100)));const v=Math.max(1,Math.min(wells.length-n-1,Math.floor(wells.length*ratios[1]/100)));return [wells.slice(0,n),wells.slice(n,n+v),wells.slice(n+v)].map(w=>a.filter(r=>w.includes(r.well_id)));}else a.sort((a,b)=>String(a.date).localeCompare(String(b.date)));const n=Math.floor(a.length*ratios[0]/100),v=Math.floor(a.length*ratios[1]/100);return [a.slice(0,n),a.slice(n,n+v),a.slice(n+v)];}
export function regressionMetrics(actual,pred){const pairs=actual.map((v,i)=>[v,pred[i]]).filter(x=>x.every(finite)).map(x=>x.map(Number));if(!pairs.length)return null;const y=pairs.map(x=>x[0]),m=mean(y),errors=pairs.map(([a,b])=>b-a),ss=y.reduce((s,x)=>s+(x-m)**2,0);const nz=pairs.filter(x=>Math.abs(x[0])>1e-8);return {MAE:mean(errors.map(Math.abs)),RMSE:Math.sqrt(mean(errors.map(x=>x*x))),R2:ss>1e-12?1-errors.reduce((s,x)=>s+x*x,0)/ss:null,MAPE:nz.length?100*mean(nz.map(([a,b])=>Math.abs((b-a)/a))):null,N:pairs.length};}
export function classificationMetrics(y,p){if(!y.length)return null;let tp=0,tn=0,fp=0,fn=0;y.forEach((v,i)=>{if(v===1&&p[i]===1)tp++;else if(v===0&&p[i]===0)tn++;else if(v===0)fp++;else fn++;});const precision=tp+fp?tp/(tp+fp):0,recall=tp+fn?tp/(tp+fn):0;return {Accuracy:(tp+tn)/y.length,Precision:precision,Recall:recall,F1:precision+recall?2*precision*recall/(precision+recall):0,FPR:fp+tn?fp/(fp+tn):null,TP:tp,TN:tn,FP:fp,FN:fn,N:y.length};}
export function ruleScan(rows,threshold={decline:15,water:3,pressure:.5}){const groups=Object.groupBy(normalizeRows(rows),r=>r.well_id??'未知井');const out=[];for(const [well,rs]of Object.entries(groups)){rs.sort((a,b)=>String(a.date).localeCompare(String(b.date)));for(let i=1;i<rs.length;i++){const r=rs[i],prev=rs[i-1];const push=(rule,level,evidence,cause,action)=>out.push({well_id:well,date:r.date,rule,level,evidence,cause,action,status:'待现场核实'});if(i>=3){const base=rs[i-3];const recent=rs.slice(i-2,i+1);const consecutive=recent.every((x,j)=>Date.parse(x.date)-Date.parse(rs[i-3+j].date)===86400000);if(base.oil>0&&consecutive&&recent.every(x=>finite(x.oil)&&x.oil<base.oil*(1-threshold.decline/100)))push('oil-decline','红',`日产油较3日前下降>${threshold.decline}%，连续3天`,'供液或生产制度变化待排查','核对计量、停井/措施记录，再结合压力与工况检查');}if(finite(r.water_cut)&&finite(prev.water_cut)&&r.water_cut-prev.water_cut>20)push('water-jump','红',`含水率单次上升${(r.water_cut-prev.water_cut).toFixed(1)}个百分点`,'见水变化或计量异常待排查','复核含水测量，联合示踪剂和注采响应确认');if(finite(r.pressure)&&finite(prev.pressure)&&Math.abs(r.pressure-prev.pressure)>threshold.pressure)push('pressure','黄',`井下压力变化${(r.pressure-prev.pressure).toFixed(2)}兆帕`,'工况或压力测量变化','核对开关井及传感器，结合试井解释');if(finite(r.pump_efficiency)&&finite(prev.pump_efficiency)&&r.pump_efficiency<prev.pump_efficiency-5)push('pump','蓝','泵效下降超过5个百分点','泵况变化待核实','检查示功图和检泵记录');
if(finite(r.liquid)&&finite(prev.liquid)&&prev.liquid>0&&r.liquid>prev.liquid*1.2)push('liquid-rise','黄','日产液较上条记录增加超过20%','生产制度、见水或计量变化待核查','核对含水、管柱与计量记录');
if(finite(r.water_cut)&&finite(prev.water_cut)&&prev.water_cut-r.water_cut>5)push('water-drop','蓝','含水率下降超过5个百分点','层间贡献或计量变化待核实','核对分层测试与计量制度');
const monthBase=rs.slice(0,i).findLast(x=>Date.parse(r.date)-Date.parse(x.date)>=28*86400000&&Date.parse(r.date)-Date.parse(x.date)<=35*86400000);
if(monthBase&&finite(r.water_cut)&&finite(monthBase.water_cut)&&r.water_cut-monthBase.water_cut>threshold.water)push('water-month','黄',`约月间含水率上升超过${threshold.water}个百分点`,'含水上升偏快','对照注采调整与分层监测');
if(finite(r.expected_oil)&&r.expected_oil>0&&finite(r.oil)&&Math.abs(r.oil-r.expected_oil)/r.expected_oil>.2)push('forecast-residual','黄','产油偏离独立预测超过20%','生产趋势异常待核实','核对预测适用工况及措施影响');
if(finite(r.injection_pressure)&&finite(prev.injection_pressure)){const delta=r.injection_pressure-prev.injection_pressure;if(delta>2)push('injection-pressure-rise','黄','注水压力较上条记录上升超过2兆帕','吸水能力下降线索，持续性待核查','结合注入量和吸水指数判断');if(delta< -1)push('injection-pressure-drop','黄','注水压力较上条记录下降超过1兆帕','管柱或地层变化待核实','结合完整性测试检查，避免直接推断破裂');}
if(finite(r.liquid_level)&&finite(prev.liquid_level)&&r.liquid_level>prev.liquid_level+10)push('fluid-level','蓝','动液面深度增加超过10米（研究阈值）','供液条件变化待核实','结合泵挂深度及示功图确认');
const oilDrop=finite(r.oil)&&prev.oil>0&&r.oil<prev.oil*.85,card=String(r.pump_card_class??'');
if(card&&card!=='正常')push('pump-card','蓝',`示功图解释：${card}`,'工况异常解释待核实','检查原始示功图与解释模型可信度');
if(oilDrop&&card.includes('供液不足')&&finite(r.liquid_level)&&finite(prev.liquid_level)&&r.liquid_level>prev.liquid_level)push('fusion-supply','红','产油下降 + 动液面加深 + 示功图供液不足','供液能力下降候选原因','补充地层压力与试井资料，区分地层与井筒因素');
if(oilDrop&&card.includes('漏失')&&finite(r.pump_efficiency)&&finite(prev.pump_efficiency)&&r.pump_efficiency<prev.pump_efficiency)push('fusion-pump','红','产油下降 + 示功图漏失 + 泵效下降','泵况故障候选原因','核对检泵和阀件检查结果');
if(oilDrop&&finite(r.water_cut)&&finite(prev.water_cut)&&r.water_cut>prev.water_cut&&finite(r.response_strength)&&r.response_strength>.7)push('fusion-channel','红','产油下降 + 含水上升 + 强注采响应','优势通道或水窜候选原因','结合示踪剂、分层监测与注采调整确认');
if(finite(r.injection_pressure)&&finite(prev.injection_pressure)&&r.injection_pressure>prev.injection_pressure&&finite(r.absorption_index)&&finite(prev.absorption_index)&&r.absorption_index<prev.absorption_index&&finite(r.injection)&&finite(prev.injection)&&r.injection<prev.injection)push('fusion-injectivity','红','注入压力上升 + 吸水指数下降 + 注入量下降','近井污染或堵塞候选原因','通过分层测试、洗井和水质检查排查');}}return out;}
export function classifyWell(rows,asof){const rs=[...rows].sort((a,b)=>String(a.date).localeCompare(String(b.date)));const r=rs.at(-1);if(!r)return '未分类';const now=Date.parse(asof??r.date);if(r.measure_date&&now-Date.parse(r.measure_date)>=0&&now-Date.parse(r.measure_date)<=92*86400000)return '措施井';if(r.commission_date&&now-Date.parse(r.commission_date)>=0&&now-Date.parse(r.commission_date)<=183*86400000)return '新井';return r.commission_date?'常规井':'投产/措施日期待补充';}
export function quantile(a,q){const b=[...a].sort((a,b)=>a-b);return b[Math.min(b.length-1,Math.max(0,Math.floor((b.length-1)*q)))];}
